        *) printf "Unknown interface language/key: %s/%s\n" "$LANGUAGE" "$key" >&2; return 1 ;;
    esac
    for argument in "$@"; do
        token="{$index}"
        value="${value//"$token"/"$argument"}"
        index=$((index + 1))
    done
    printf "%s\n" "$value"
}
